'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let pos = 0;

const L = Number(input[pos++]);
const C = Number(input[pos++]);

const equations = [];
const present = new Array(676).fill(false);

function variableIndex(name) {
  return (name.charCodeAt(0) - 97) * 26 + name.charCodeAt(1) - 97;
}

function addEquation(variables, sum) {
  const coeffs = new Map();
  for (const v of variables) {
    coeffs.set(v, (coeffs.get(v) || 0) + 1);
    present[v] = true;
  }
  equations.push({ coeffs, rhs: sum, degree: coeffs.size });
}

for (let r = 0; r < L; r++) {
  const variables = [];
  for (let c = 0; c < C; c++) {
    variables.push(variableIndex(input[pos++]));
  }
  addEquation(variables, BigInt(input[pos++]));
}

const columnSums = [];
for (let c = 0; c < C; c++) columnSums.push(BigInt(input[pos++]));

for (let c = 0; c < C; c++) {
  const variables = [];
  for (let r = 0; r < L; r++) {
    variables.push(variableIndex(input[2 + r * (C + 1) + c]));
  }
  addEquation(variables, columnSums[c]);
}

const incidence = Array.from({ length: 676 }, () => []);
for (let i = 0; i < equations.length; i++) {
  for (const v of equations[i].coeffs.keys()) incidence[v].push(i);
}

const queue = [];
for (let i = 0; i < equations.length; i++) {
  if (equations[i].degree === 1) queue.push(i);
}

const known = new Array(676).fill(false);
const values = new Array(676);
let head = 0;

while (head < queue.length) {
  const eqIndex = queue[head++];
  const eq = equations[eqIndex];
  if (eq.degree !== 1) continue;

  let variable = -1;
  let coefficient = 0;
  for (const [v, count] of eq.coeffs) {
    variable = v;
    coefficient = count;
    break;
  }

  if (known[variable]) continue;

  const value = eq.rhs / BigInt(coefficient);
  known[variable] = true;
  values[variable] = value;

  for (const affectedIndex of incidence[variable]) {
    const affected = equations[affectedIndex];
    const count = affected.coeffs.get(variable);
    if (count === undefined) continue;

    affected.rhs -= BigInt(count) * value;
    affected.coeffs.delete(variable);
    affected.degree--;

    if (affected.degree === 1) queue.push(affectedIndex);
  }
}

const output = [];
for (let v = 0; v < 676; v++) {
  if (!present[v]) continue;
  const name = String.fromCharCode(97 + Math.floor(v / 26)) +
               String.fromCharCode(97 + (v % 26));
  output.push(`${name} ${values[v]}`);
}

console.log(output.join('\n'));
